// three.js side of the bird models: one shared skinned geometry (plus a pale leucistic
// variant sharing every attribute but the colours) per species, one shared material for
// every bird, and cheap per-bird instances (a SkinnedMesh + its 15 bones). The geometry
// itself is generated by the pure mesh.js; the pose comes from the pure pose.js.

import * as THREE from 'three';
import { buildBirdMesh, BONE } from './mesh.js';
import { animProfile, stanceOffset, legBend } from './pose.js';
import { parseHex, toLinear, mix } from './color.js';
import { clamp } from './rig.js';

let material = null;

/** The one material every bird shares (vertex colours, soft Lambert shading). */
export function birdMaterial() {
  if (!material) {
    material = new THREE.MeshLambertMaterial({ vertexColors: true });
    material.name = 'birds';
  }
  return material;
}

const IDENTITY = new THREE.Matrix4();
const BLACK = [0.02, 0.02, 0.025];

/**
 * Build (or fetch from `cache`) the shared template for a species: geometry, the
 * leucistic geometry, bone layout and animation profile. Templates are immutable and
 * shared by every bird of that species.
 */
export function birdTemplate(species, cache) {
  const hit = cache?.get(species);
  if (hit) return hit;
  const data = buildBirdMesh(species);
  const geo = new THREE.BufferGeometry();
  const pos = new THREE.BufferAttribute(data.positions, 3);
  const nrm = new THREE.BufferAttribute(data.normals, 3);
  const si = new THREE.Uint16BufferAttribute(data.skinIndex, 4);
  const sw = new THREE.BufferAttribute(data.skinWeight, 4);
  geo.setAttribute('position', pos);
  geo.setAttribute('normal', nrm);
  geo.setAttribute('color', new THREE.BufferAttribute(data.colors, 3));
  geo.setAttribute('skinIndex', si);
  geo.setAttribute('skinWeight', sw);
  // The rare (leucistic) variant shares positions/normals/skinning on the GPU.
  const geoRare = new THREE.BufferGeometry();
  geoRare.setAttribute('position', pos);
  geoRare.setAttribute('normal', nrm);
  geoRare.setAttribute('color', new THREE.BufferAttribute(data.colorsRare, 3));
  geoRare.setAttribute('skinIndex', si);
  geoRare.setAttribute('skinWeight', sw);
  const R = data.rig;
  const radius = data.radius * 1.3 + R.legs.len;
  for (const g of [geo, geoRare]) g.boundingSphere = new THREE.Sphere(new THREE.Vector3(), radius);

  const boneInverses = data.bones.map((b) => new THREE.Matrix4().makeTranslation(-b.pos[0], -b.pos[1], -b.pos[2]));
  // A distant speck takes the bird's overall darkened tone.
  const back = data.palette.back, belly = data.palette.belly;
  const tone = mix(back, belly, 0.25);
  const speck = toLinear(mix(tone, BLACK, 0.55));
  const speckRare = toLinear(mix(mix(tone, parseHex('#f2ede0'), 0.7), BLACK, 0.3));
  const tpl = {
    species,
    data,
    rig: R,
    profile: animProfile(species, R),
    geometry: geo,
    geometryRare: geoRare,
    boneInverses,
    radius,
    speckColor: new THREE.Color(speck[0], speck[1], speck[2]),
    speckColorRare: new THREE.Color(speckRare[0], speckRare[1], speckRare[2]),
    pool: [],
    dispose() { geo.dispose(); geoRare.dispose(); },
  };
  cache?.set(species, tpl);
  return tpl;
}

/**
 * A new rigged bird of a species: { object (SkinnedMesh — add it to the scene), bones,
 * template, rare }. Geometry and material are shared; only the skeleton is per bird.
 * @param species core.Species (welcome.species[i])
 * @param {{rare?: boolean, cache?: Map}} opts rare = leucistic plumage
 */
export function buildBirdModel(species, opts = {}) {
  const tpl = birdTemplate(species, opts.cache);
  return instantiate(tpl, !!opts.rare);
}

/** Make an instance from a template. */
export function instantiate(tpl, rare = false) {
  const bones = tpl.data.bones.map((b) => {
    const bone = new THREE.Bone();
    bone.name = b.name;
    bone.position.set(b.rel[0], b.rel[1], b.rel[2]);
    bone.rotation.order = b.name.startsWith('wing') ? 'YZX' : 'YXZ';
    return bone;
  });
  tpl.data.bones.forEach((b, i) => { if (b.parent >= 0) bones[b.parent].add(bones[i]); });
  const mesh = new THREE.SkinnedMesh(rare ? tpl.geometryRare : tpl.geometry, birdMaterial());
  mesh.name = 'bird';
  mesh.add(bones[0]);
  mesh.bind(new THREE.Skeleton(bones, tpl.boneInverses), IDENTITY);
  // Local-space bounds that hold every pose; avoids per-pose recomputation.
  mesh.boundingSphere = new THREE.Sphere(new THREE.Vector3(0, tpl.rig.legs.len, 0), tpl.radius);
  mesh.frustumCulled = true;
  mesh.matrixAutoUpdate = true;
  return { object: mesh, bones, template: tpl, rare, stance: { y: 0, z: 0 } };
}

/** Switch an instance between normal and leucistic plumage. */
export function setRare(view, rare) {
  if (view.rare === rare) return;
  view.rare = rare;
  view.object.geometry = rare ? view.template.geometryRare : view.template.geometry;
}

const smooth = (t) => (t <= 0 ? 0 : t >= 1 ? 1 : t * t * (3 - 2 * t));
const TINY = 1e-4;

/** Write a pose (pose.js) onto an instance's bones. */
export function applyPose(view, pose) {
  const b = view.bones, tpl = view.template, R = tpl.rig, P = tpl.profile;
  const st = stanceOffset(R, P, pose, view.stance);

  const body = b[BONE.body];
  body.position.set(0, st.y, st.z);
  body.rotation.set(pose.bodyPitch, 0, -pose.bodyRoll);
  body.scale.setScalar(pose.fluff);

  const neck = b[BONE.neck];
  neck.rotation.x = pose.neckPitch;
  const ns = clamp(pose.neckScale, 0.4, 1.4);
  neck.scale.setScalar(ns);

  const head = b[BONE.head];
  head.rotation.set(pose.headPitch, -pose.headYaw, pose.headRoll);
  head.scale.setScalar(1 / ns);

  b[BONE.jaw].rotation.x = -Math.max(0, pose.jaw);
  b[BONE.throat].scale.setScalar(Math.max(0.3, pose.throat));
  b[BONE.twig].scale.setScalar(pose.twig > 0.5 ? 1 : TINY);

  const tail = b[BONE.tail];
  tail.rotation.set(-pose.tailPitch, pose.tailYaw, 0);
  tail.scale.set(1 + (R.tail.spread - 1) * clamp(pose.tailSpread, 0, 1), 1, 1);

  // Spread wings collapse into the shoulder as they fold; the flank shells grow out of
  // the body at the same time (see mesh.js).
  const fold = clamp(pose.fold, 0, 1);
  const ws = Math.max(TINY, 1 - smooth(fold));
  const sweep = -(clamp(pose.sweep, 0, 1) * 1.0 + fold * 1.1);
  const wr = b[BONE.wingR], wl = b[BONE.wingL];
  wr.rotation.set(0, sweep, pose.flapR);
  wl.rotation.set(0, -sweep, -pose.flapL);
  wr.scale.setScalar(ws); wl.scale.setScalar(ws);
  b[BONE.handR].rotation.z = pose.hand;
  b[BONE.handL].rotation.z = -pose.hand;
  const cs = 0.3 + 0.7 * smooth(fold);
  const cr = b[BONE.coverR], cl = b[BONE.coverL];
  cr.scale.setScalar(cs); cl.scale.setScalar(cs);
  cr.rotation.z = pose.coverLiftR;
  cl.rotation.z = -pose.coverLiftL;

  // Legs hang vertically whatever the body pitch (except when gripping a trunk),
  // stride when walking, and tuck (small birds) or trail (long-legged birds) in flight.
  const tuck = clamp(pose.legTuck, 0, 1);
  const counter = -pose.bodyPitch * (1 - clamp(pose.climb, 0, 1));
  const bend = legBend(pose.crouch);
  const trail = P.legsTrail ? 1.45 : 1.2;
  const shrink = P.legsTrail ? 1 : 1 - 0.65 * tuck;
  setLeg(b[BONE.legL], pose.strideL, counter, tuck, trail, bend, shrink);
  setLeg(b[BONE.legR], pose.strideR, counter, tuck, trail, bend, shrink);
}

function setLeg(leg, stride, counter, tuck, trail, bend, shrink) {
  leg.rotation.x = (counter + stride) * (1 - tuck) - trail * tuck;
  leg.scale.set(shrink, bend * shrink, shrink);
}
